local BranSeparatorMaker = {}
local PRODUCTS = {
    iron_branseparator = { name = "Železni ločilec otrob", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni ločilec otrob za mlinarje." },
    bronze_branseparator = { name = "Bronast ločilec otrob", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast ločilec otrob za mlinarje." },
    silver_branseparator = { name = "Srebrn ločilec otrob", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn ločilec otrob za mlinarje." },
    gilded_branseparator = { name = "Pozlačen ločilec otrob", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen ločilec otrob za mlinarje." },
    jewel_set_branseparator = { name = "Draguljast ločilec otrob", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast ločilec otrob za mlinarje." },
    royal_sovereign_branseparator = { name = "Kraljevski suveren ločilec otrob", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren ločilec otrob z biseri za krono." },
}
local BUILDINGS = {
    branseparator_workshop = { name = "Branseparator delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    branseparator_house = { name = "Branseparator hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_branseparator_atelier = { name = "Mojstrski branseparator atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_branseparator_palace = { name = "Suverena branseparator palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
BranSeparatorMaker.ironStock=18; BranSeparatorMaker.bronzeStock=14; BranSeparatorMaker.woodStock=10; BranSeparatorMaker.leatherStock=8; BranSeparatorMaker.silverStock=8; BranSeparatorMaker.goldStock=6; BranSeparatorMaker.jewelStock=4; BranSeparatorMaker.pearlStock=4
BranSeparatorMaker.productStock = {}; BranSeparatorMaker.buildings = {}; BranSeparatorMaker.maker = nil; BranSeparatorMaker.activeMaking = {}; BranSeparatorMaker.totalProducts = 0; BranSeparatorMaker.dayTimer = 0
function BranSeparatorMaker.init() BranSeparatorMaker.ironStock=18; BranSeparatorMaker.bronzeStock=14; BranSeparatorMaker.woodStock=10; BranSeparatorMaker.leatherStock=8; BranSeparatorMaker.silverStock=8; BranSeparatorMaker.goldStock=6; BranSeparatorMaker.jewelStock=4; BranSeparatorMaker.pearlStock=4; BranSeparatorMaker.productStock={}; BranSeparatorMaker.buildings={}; BranSeparatorMaker.maker=nil; BranSeparatorMaker.activeMaking={}; BranSeparatorMaker.totalProducts=0; BranSeparatorMaker.dayTimer=0; print("[BranSeparatorMaker] Royal Bran Separator Maker System initialized (6 products, 4 buildings)") end
function BranSeparatorMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BranSeparatorMaker.maker={name=n or ("Ločevalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ločevalec najet: %s (spretnost: %d)",BranSeparatorMaker.maker.name,s),"success") end; return true end
function BranSeparatorMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BranSeparatorMaker.build(id) local ok,e=BranSeparatorMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BranSeparatorMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BranSeparatorMaker.getQualityBonus() local b=0; for _,bd in ipairs(BranSeparatorMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BranSeparatorMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BranSeparatorMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BranSeparatorMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BranSeparatorMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BranSeparatorMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BranSeparatorMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BranSeparatorMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BranSeparatorMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BranSeparatorMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BranSeparatorMaker.buildings==0 then return false,"Potrebna ločevalna delavnica" end; if not BranSeparatorMaker.maker then return false,"Potreben ločevalec" end; return true end
function BranSeparatorMaker.make(pt,qty) qty=qty or 1; local ok,e=BranSeparatorMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BranSeparatorMaker.ironStock=BranSeparatorMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BranSeparatorMaker.bronzeStock=BranSeparatorMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BranSeparatorMaker.woodStock=BranSeparatorMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BranSeparatorMaker.leatherStock=BranSeparatorMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BranSeparatorMaker.silverStock=BranSeparatorMaker.silverStock-d.silverCost*qty end; if d.goldCost then BranSeparatorMaker.goldStock=BranSeparatorMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BranSeparatorMaker.jewelStock=BranSeparatorMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BranSeparatorMaker.pearlStock=BranSeparatorMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BranSeparatorMaker.maker then t=math.max(1,t-math.floor(BranSeparatorMaker.maker.skill/13)) end; table.insert(BranSeparatorMaker.activeMaking,{id="branseparator_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BranSeparatorMaker.completeMaking(m) local q=1.0+(BranSeparatorMaker.getQualityBonus()/100); if BranSeparatorMaker.maker then q=q+(BranSeparatorMaker.maker.skill/140) end; q=math.min(2.5,q); BranSeparatorMaker.productStock[m.productType]=(BranSeparatorMaker.productStock[m.productType] or 0)+m.quantity; BranSeparatorMaker.totalProducts=BranSeparatorMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BranSeparatorMaker.maker then BranSeparatorMaker.maker.itemsMade=BranSeparatorMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BranSeparatorMaker.maker.skill=math.min(100,BranSeparatorMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ločevalec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"branseparator.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BranSeparatorMaker.update(dt) if not _G.state then return end; BranSeparatorMaker.dayTimer=BranSeparatorMaker.dayTimer+dt; if BranSeparatorMaker.dayTimer>=30 then BranSeparatorMaker.dayTimer=0; for i=#BranSeparatorMaker.activeMaking,1,-1 do local m=BranSeparatorMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BranSeparatorMaker.completeMaking(m); table.remove(BranSeparatorMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BranSeparatorMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BranSeparatorMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BranSeparatorMaker.getStats() return {ironStock=BranSeparatorMaker.ironStock,bronzeStock=BranSeparatorMaker.bronzeStock,woodStock=BranSeparatorMaker.woodStock,leatherStock=BranSeparatorMaker.leatherStock,silverStock=BranSeparatorMaker.silverStock,goldStock=BranSeparatorMaker.goldStock,jewelStock=BranSeparatorMaker.jewelStock,pearlStock=BranSeparatorMaker.pearlStock,productStock=BranSeparatorMaker.productStock,numBuildings=#BranSeparatorMaker.buildings,hasMaker=BranSeparatorMaker.maker~=nil,makerName=BranSeparatorMaker.maker and BranSeparatorMaker.maker.name or "—",makerSkill=BranSeparatorMaker.maker and BranSeparatorMaker.maker.skill or 0,activeMaking=#BranSeparatorMaker.activeMaking,totalProducts=BranSeparatorMaker.totalProducts} end
return BranSeparatorMaker
